import React, { useState } from 'react';
import { Form, Button, Container, Row, Col, Alert, Spinner } from 'react-bootstrap';
import axios from 'axios';

const AnimalRescueRequestForm = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    contactNumber: '',
    email: '',
    tag: '',
    concern: '',
    locationNote: '',
    photo: null,
  });

  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState(null);
  const [requestId, setRequestId] = useState(null);

  const tagOptions = ['Neglect', 'Accident', 'Cruelty', 'Lost', 'Missing'];

  const handleChange = (e) => {
    const { name, value, files } = e.target;
    if (name === 'photo') {
      setFormData({ ...formData, photo: files[0] });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const resetForm = () => {
    setFormData({
      fullName: '',
      contactNumber: '',
      email: '',
      tag: '',
      concern: '',
      locationNote: '',
      photo: null,
    });
    // Reset file input by clearing its value
    const fileInput = document.querySelector('input[type="file"]');
    if (fileInput) fileInput.value = '';
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    
    try {
      // Create FormData object for file upload
      const submitData = new FormData();
      
      // Append all form fields to FormData
      Object.keys(formData).forEach(key => {
        if (key === 'photo' && formData[key]) {
          submitData.append(key, formData[key]);
        } else if (key !== 'photo') {
          submitData.append(key, formData[key]);
        }
      });
      
      // Send data to backend API
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/rescue-requests`, 
        submitData,
        {
          headers: {
            'Content-Type': 'multipart/form-data'
          }
        }
      );
      
      if (response.data.success) {
        setSubmitted(true);
        setRequestId(response.data.requestId);
        resetForm();
      } else {
        setError('Failed to submit request. Please try again.');
      }
    } catch (err) {
      console.error('Error submitting form:', err);
      setError(err.response?.data?.message || 'An error occurred while submitting your request. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container className="mt-5 mb-5">
      <h2 className="mb-4 text-deep-raspberry fw-bold">Animal Rescue Request Form</h2>
      
      {submitted && (
        <Alert variant="success">
          <Alert.Heading>Thank you for your submission!</Alert.Heading>
          <p>
            Your request has been submitted successfully with reference ID: <strong>{requestId}</strong>.
            Please keep your lines open as TAARA will try to contact you to confirm your request.
          </p>
          <hr />
          <div className="d-flex justify-content-end">
            <Button 
              variant="outline-success"
              onClick={() => setSubmitted(false)}
            >
              Submit another request
            </Button>
          </div>
        </Alert>
      )}
      
      {error && (
        <Alert variant="danger" onClose={() => setError(null)} dismissible>
          <Alert.Heading>Error!</Alert.Heading>
          <p>{error}</p>
        </Alert>
      )}
      
      {!submitted && (
        <Form onSubmit={handleSubmit}>
          <Row>
            <Col md={6}>
              <Form.Group className="mb-3" controlId="fullName">
                <Form.Label>Full Name</Form.Label>
                <Form.Control
                  type="text"
                  placeholder="Enter full name"
                  name="fullName"
                  value={formData.fullName}
                  onChange={handleChange}
                  required
                />
              </Form.Group>
            </Col>
            
            <Col md={6}>
              <Form.Group className="mb-3" controlId="contactNumber">
                <Form.Label>Contact Number</Form.Label>
                <Form.Control
                  type="tel"
                  placeholder="Enter contact number"
                  name="contactNumber"
                  value={formData.contactNumber}
                  onChange={handleChange}
                  required
                />
              </Form.Group>
            </Col>
          </Row>

          <Form.Group className="mb-3" controlId="email">
            <Form.Label>Email Address</Form.Label>
            <Form.Control
              type="email"
              placeholder="Enter email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </Form.Group>

          <Form.Group className="mb-3">
            <Form.Label>Emergency Tag</Form.Label>
            <div className="d-flex flex-wrap gap-3">
              {tagOptions.map((tag, idx) => (
                <Form.Check
                  key={idx}
                  label={tag}
                  type="radio"
                  id={`tag-${idx}`}
                  name="tag"
                  value={tag}
                  checked={formData.tag === tag}
                  onChange={handleChange}
                  required
                  className="me-3"
                />
              ))}
            </div>
          </Form.Group>

          <Form.Group className="mb-3" controlId="concern">
            <Form.Label>Describe the Situation</Form.Label>
            <Form.Control
              as="textarea"
              rows={4}
              placeholder="Please provide details about the animal's condition, behavior, and any immediate concerns"
              name="concern"
              value={formData.concern}
              onChange={handleChange}
              required
            />
          </Form.Group>

          <Form.Group className="mb-3" controlId="photo">
            <Form.Label>Upload Photo (Optional)</Form.Label>
            <Form.Control
              type="file"
              name="photo"
              onChange={handleChange}
              accept="image/*"
            />
            <Form.Text className="text-muted">
              Upload a clear photo of the animal to help us better understand the situation.
            </Form.Text>
          </Form.Group>

          <Form.Group className="mb-3" controlId="locationNote">
            <Form.Label>Location Details</Form.Label>
            <Form.Control
              as="textarea"
              rows={3}
              placeholder="Provide exact address or detailed location description. You can also paste a Google Maps link."
              name="locationNote"
              value={formData.locationNote}
              onChange={handleChange}
              required
            />
          </Form.Group>

          <Alert variant="info">
            <i className="bi bi-info-circle me-2"></i>
            Please keep your lines open as TAARA will try to contact you to confirm your request.
            In case of extreme emergency, please call our hotline at (123) 456-7890.
          </Alert>

          <div className="d-grid gap-2">
            <Button 
              variant="primary" 
              type="submit" 
              size="lg"
              disabled={loading}
            >
              {loading ? (
                <>
                  <Spinner
                    as="span"
                    animation="border"
                    size="sm"
                    role="status"
                    aria-hidden="true"
                    className="me-2"
                  />
                  Submitting...
                </>
              ) : (
                'Submit Rescue Request'
              )}
            </Button>
          </div>
        </Form>
      )}
    </Container>
  );
};

export default AnimalRescueRequestForm;