import React, { useState } from 'react';
import axios from 'axios';
import { format } from 'date-fns';
import { Button, Form, Row, Col, Container, Alert } from 'react-bootstrap';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';

const AnimalReportForm = ({ darkMode }) => {
  // Form state
  const [formData, setFormData] = useState({
    date: new Date(),
    name: '',
    breed: '',
    address: '',
    reporter: '',
    remarks: '',
    image: null
  });

  // Validation errors
  const [errors, setErrors] = useState({
    name: false,
    breed: false,
    address: false,
    reporter: false
  });

  // Submission status
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [submitError, setSubmitError] = useState('');

  // Predefined list of breeds
  const breedOptions = [
    'Labrador Retriever',
    'German Shepherd',
    'Golden Retriever',
    'Bulldog',
    'Beagle',
    'Poodle',
    'Rottweiler',
    'Yorkshire Terrier',
    'Boxer',
    'Dachshund',
    'Other'
  ];

  // Handle input changes
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value
    }));

    // Clear error when user starts typing
    if (errors[name]) {
      setErrors((prev) => ({
        ...prev,
        [name]: false
      }));
    }
  };

  // Handle file input
  const handleFileChange = (e) => {
    setFormData((prev) => ({
      ...prev,
      image: e.target.files[0]
    }));
  };

  // Handle date change
  const handleDateChange = (date) => {
    setFormData((prev) => ({
      ...prev,
      date
    }));
  };

  // Validate form
  const validateForm = () => {
    const newErrors = {
      name: formData.name.trim() === '',
      breed: formData.breed === '',
      address: formData.address.trim() === '',
      reporter: formData.reporter.trim() === ''
    };

    setErrors(newErrors);
    return !Object.values(newErrors).some((error) => error);
  };

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);
    setSubmitError('');

    try {
      // Format the date as string for your model
      const formattedDate = format(formData.date, 'yyyy-MM-dd');

      const formPayload = new FormData();
      formPayload.append('date', formattedDate);
      formPayload.append('name', formData.name);
      formPayload.append('breed', formData.breed);
      formPayload.append('address', formData.address);
      formPayload.append('reporter', formData.reporter);
      formPayload.append('remarks', formData.remarks);
      if (formData.image) {
        formPayload.append('image', formData.image);
      }

      const response = await axios.post('http://localhost:5000/api/animals', formPayload, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });

      if (response.status === 201) {
        setSubmitSuccess(true);
        // Reset form
        setFormData({
          date: new Date(),
          name: '',
          breed: '',
          address: '',
          reporter: '',
          remarks: '',
          image: null
        });
      }
    } catch (error) {
      console.error('Error submitting form:', error);
      setSubmitError(error.response?.data?.message || 'Failed to submit form. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Container style={{ maxWidth: '900px', marginTop: '30px' }}>
      <h2 className={`text-center mb-4 ${darkMode ? 'text-light' : 'text-deep-raspberry'}`}>Animal Report Form</h2>

      {submitSuccess && (
        <Alert variant="success" onClose={() => setSubmitSuccess(false)} dismissible>
          Animal report submitted successfully!
        </Alert>
      )}

      {submitError && (
        <Alert variant="danger" onClose={() => setSubmitError('')} dismissible>
          {submitError}
        </Alert>
      )}

      <Form onSubmit={handleSubmit}>
        <Row className="mb-3">
          {/* Date Field */}
          <Col xs={12} md={6}>
            <Form.Group controlId="date">
              <Form.Label className={darkMode ? 'text-light' : ''}>Report Date</Form.Label>
              <DatePicker
                selected={formData.date}
                onChange={handleDateChange}
                dateFormat="yyyy-MM-dd"
                className={`form-control ${darkMode ? 'bg-dark text-light border-secondary' : ''}`}
                required
              />
            </Form.Group>
          </Col>

          {/* Name Field */}
          <Col xs={12} md={6}>
            <Form.Group controlId="name">
              <Form.Label className={darkMode ? 'text-light' : ''}>Animal Name</Form.Label>
              <Form.Control
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                required
                isInvalid={errors.name}
                placeholder="Enter animal name"
                className={darkMode ? 'bg-dark text-light border-secondary' : ''}
              />
              {errors.name && (
                <Form.Control.Feedback type="invalid">Animal name is required</Form.Control.Feedback>
              )}
            </Form.Group>
          </Col>
        </Row>

        <Row className="mb-3">
          {/* Breed Field */}
          <Col xs={12} md={6}>
            <Form.Group controlId="breed">
              <Form.Label className={darkMode ? 'text-light' : ''}>Breed</Form.Label>
              <Form.Control
                as="select"
                name="breed"
                value={formData.breed}
                onChange={handleChange}
                required
                isInvalid={errors.breed}
                className={darkMode ? 'bg-dark text-light border-secondary' : ''}
              >
                <option value="">Select a breed</option>
                {breedOptions.map((breed) => (
                  <option key={breed} value={breed}>
                    {breed}
                  </option>
                ))}
              </Form.Control>
              {errors.breed && (
                <Form.Control.Feedback type="invalid">Breed selection is required</Form.Control.Feedback>
              )}
            </Form.Group>
          </Col>

          {/* Reporter Field */}
          <Col xs={12} md={6}>
            <Form.Group controlId="reporter">
              <Form.Label className={darkMode ? 'text-light' : ''}>Reporter Name</Form.Label>
              <Form.Control
                type="text"
                name="reporter"
                value={formData.reporter}
                onChange={handleChange}
                required
                isInvalid={errors.reporter}
                placeholder="Enter reporter's name"
                className={darkMode ? 'bg-dark text-light border-secondary' : ''}
              />
              {errors.reporter && (
                <Form.Control.Feedback type="invalid">Reporter name is required</Form.Control.Feedback>
              )}
            </Form.Group>
          </Col>
        </Row>

        <Row className="mb-3">
          {/* Address Field */}
          <Col xs={12}>
            <Form.Group controlId="address">
              <Form.Label className={darkMode ? 'text-light' : ''}>Address</Form.Label>
              <Form.Control
                as="textarea"
                name="address"
                value={formData.address}
                onChange={handleChange}
                rows={3}
                required
                isInvalid={errors.address}
                placeholder="Enter address details"
                className={darkMode ? 'bg-dark text-light border-secondary' : ''}
              />
              {errors.address && (
                <Form.Control.Feedback type="invalid">Address is required</Form.Control.Feedback>
              )}
            </Form.Group>
          </Col>
        </Row>

        <Row className="mb-3">
          {/* Remarks Field */}
          <Col xs={12}>
            <Form.Group controlId="remarks">
              <Form.Label className={darkMode ? 'text-light' : ''}>Remarks</Form.Label>
              <Form.Control
                as="textarea"
                name="remarks"
                value={formData.remarks}
                onChange={handleChange}
                rows={3}
                placeholder="Add any remarks or details"
                className={darkMode ? 'bg-dark text-light border-secondary' : ''}
              />
            </Form.Group>
          </Col>
        </Row>

        <Row className="mb-3">
          {/* Image Upload */}
          <Col xs={12}>
            <Form.Group controlId="image">
              <Form.Label className={darkMode ? 'text-light' : ''}>Animal Image (Optional)</Form.Label>
              <Form.Control
                type="file"
                onChange={handleFileChange}
                accept="image/*"
                className={darkMode ? 'bg-dark text-light border-secondary' : ''}
              />
            </Form.Group>
          </Col>
        </Row>

        {/* Submit Button */}
        <Row>
          <Col xs={12}>
            <Button
              type="submit"
              variant="deep-raspberry"
              disabled={isSubmitting}
              className="mt-3 w-100"
            >
              {isSubmitting ? 'Submitting...' : 'Submit Report'}
            </Button>
          </Col>
        </Row>
      </Form>
    </Container>
  );
};

export default AnimalReportForm;
