import React, { useState } from 'react';
import { Form, Button, Container, Alert } from 'react-bootstrap';

const ApplicationForm = () => {
  const [formData, setFormData] = useState({
    name: '',
    contact: '',
    address: '',
    petType: '',
    reason: '',
    experience: '',
    notes: '',
  });

  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const validate = () => {
    const tempErrors = {};
    if (!formData.name) tempErrors.name = 'Name is required';
    if (!formData.contact || !/\S+@\S+\.\S+/.test(formData.contact)) tempErrors.contact = 'Valid email is required';
    if (!formData.address) tempErrors.address = 'Address is required';
    if (!formData.petType) tempErrors.petType = 'Preferred pet type is required';
    if (!formData.reason) tempErrors.reason = 'Reason for adoption is required';
    return tempErrors;
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const validationErrors = validate();
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length === 0) {
      const applications = JSON.parse(localStorage.getItem('applications') || '[]');
      applications.push(formData);
      localStorage.setItem('applications', JSON.stringify(applications));

      setSubmitted(true);
      setFormData({
        name: '',
        contact: '',
        address: '',
        petType: '',
        reason: '',
        experience: '',
        notes: '',
      });
    }
  };

  return (
    <Container className="mt-5" style={{ maxWidth: '600px' }}>
      <h2 className="mb-4 text-center">Adoption Application</h2>
      {submitted && <Alert variant="success">Application submitted successfully!</Alert>}

      <Form onSubmit={handleSubmit}>
        <Form.Group className="mb-3">
          <Form.Label>Applicant Name</Form.Label>
          <Form.Control
            type="text"
            name="name"
            value={formData.name}
            onChange={handleChange}
            isInvalid={!!errors.name}
            placeholder="Enter your full name"
          />
          <Form.Control.Feedback type="invalid">{errors.name}</Form.Control.Feedback>
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Contact Information (Email)</Form.Label>
          <Form.Control
            type="email"
            name="contact"
            value={formData.contact}
            onChange={handleChange}
            isInvalid={!!errors.contact}
            placeholder="your@email.com"
          />
          <Form.Control.Feedback type="invalid">{errors.contact}</Form.Control.Feedback>
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Address</Form.Label>
          <Form.Control
            type="text"
            name="address"
            value={formData.address}
            onChange={handleChange}
            isInvalid={!!errors.address}
            placeholder="Your address"
          />
          <Form.Control.Feedback type="invalid">{errors.address}</Form.Control.Feedback>
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Preferred Type of Pet</Form.Label>
          <Form.Control
            type="text"
            name="petType"
            value={formData.petType}
            onChange={handleChange}
            isInvalid={!!errors.petType}
            placeholder="e.g. Dog, Cat"
          />
          <Form.Control.Feedback type="invalid">{errors.petType}</Form.Control.Feedback>
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Reason for Adoption</Form.Label>
          <Form.Control
            as="textarea"
            rows={2}
            name="reason"
            value={formData.reason}
            onChange={handleChange}
            isInvalid={!!errors.reason}
            placeholder="Tell us why you want to adopt"
          />
          <Form.Control.Feedback type="invalid">{errors.reason}</Form.Control.Feedback>
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Experience with Pets</Form.Label>
          <Form.Control
            as="textarea"
            rows={2}
            name="experience"
            value={formData.experience}
            onChange={handleChange}
            placeholder="Share your experience with pets"
          />
        </Form.Group>

        <Form.Group className="mb-3">
          <Form.Label>Any Additional Notes</Form.Label>
          <Form.Control
            as="textarea"
            rows={2}
            name="notes"
            value={formData.notes}
            onChange={handleChange}
            placeholder="Optional notes"
          />
        </Form.Group>

        <Button variant="primary" type="submit" className="w-100">
          Submit Application
        </Button>
      </Form>
    </Container>
  );
};

export default ApplicationForm;
